<?php
namespace app\controller;use app\service\AdminAccess;use app\service\SecretStore;use app\service\AlipayService;use app\service\GatewayCache;use app\service\RedisService;
use app\BaseController; use think\facade\Db; use think\facade\Session; use think\facade\View;
class Panel extends BaseController {
 private function quotaSig(array $u):string{$secret=trim((string)@file_get_contents((string)(getenv('LUMEN_INTEGRITY_KEY_FILE')?:'/www/server/lumenapi/integrity.key')));return hash_hmac('sha256',$u['id'].'|'.($u['quota_total']===null?'NULL':$u['quota_total']).'|'.$u['quota_used'],$secret);}
 private function guard(){return AdminAccess::guard();} private function ownerGuard(){return AdminAccess::ownerGuard();}
 private function writeAudit($action,$type=null,$id=null,$detail=null){Db::name('audit_logs')->insert(['admin_id'=>Session::get('lumen_admin_id'),'action'=>$action,'target_type'=>$type,'target_id'=>$id,'detail'=>$detail,'ip'=>request()->ip(),'created_at'=>date('Y-m-d H:i:s')]);}
 public function endpoints(){if($r=$this->guard())return $r;View::assign('items',Db::name('endpoints')->order('id','desc')->select()->toArray());View::assign('username',Session::get('lumen_admin_username'));return View::fetch(root_path().'view/admin/endpoints.html');}
 public function saveEndpoint(){if($r=$this->guard())return $r;$id=(int)input('post.id',0);$name=trim((string)input('post.name',''));$slug=trim((string)input('post.slug',''));$method=strtoupper(trim((string)input('post.method','AUTO')));$driver=trim((string)input('post.driver','http'));$requestMode=trim((string)input('post.request_mode','passthrough'));$authMode=trim((string)input('post.auth_mode','both'));$accessLevel=trim((string)input('post.access_level','public'));$url=trim((string)input('post.target_url',''));$handler=trim((string)input('post.handler_name',''));$upAuth=trim((string)input('post.upstream_auth_type','none'));$upAuthName=trim((string)input('post.upstream_auth_name',''));$upSecret=(string)input('post.upstream_auth_secret','');$upHeaders=trim((string)input('post.upstream_headers',''));if($name===''||!preg_match('/^[a-zA-Z0-9_-]{2,100}$/',$slug)||!in_array($method,['AUTO','GET','POST','PUT','PATCH','DELETE'],true)||!in_array($driver,['http','json','proxy','handler'],true)||!in_array($requestMode,['passthrough','defined'],true)||!in_array($authMode,['both','bearer','query','none'],true)||!in_array($accessLevel,['public','admin'],true))return response('参数不合法',422);if($driver==='handler'&&!preg_match('#^[A-Za-z][A-Za-z0-9_]{0,80}(?:/[A-Za-z][A-Za-z0-9_]{0,80})*$#',$handler))return response('Handler 名称不合法',422);if($url!==''&&!preg_match('#^https?://#i',$url))return response('目标 URL 必须使用 http/https',422);if(!in_array($upAuth,['none','bearer','header','query','basic'],true))return response('上游认证方式不合法',422);if(in_array($upAuth,['header','query','basic'],true)&&$upAuthName==='')return response('当前上游认证方式必须填写认证名称：Header 名称、Query 参数名或 Basic Auth 用户名',422);$data=['name'=>$name,'slug'=>$slug,'method'=>$method,'driver'=>$driver,'request_mode'=>$requestMode,'auth_mode'=>$authMode,'access_level'=>$accessLevel,'cost_per_call'=>max(0,(int)input('post.cost_per_call',0)),'success_mode'=>in_array(input('post.success_mode','http_2xx'),['http_2xx','json_field'],true)?input('post.success_mode','http_2xx'):'http_2xx','success_json_field'=>trim((string)input('post.success_json_field',''))?:null,'success_json_value'=>(string)input('post.success_json_value',''),'target_url'=>$url?:null,'handler_name'=>$handler?:null,'upstream_auth_type'=>$upAuth,'upstream_auth_name'=>$upAuthName?:null,'upstream_headers'=>$upHeaders?:null,'status'=>(int)input('post.status',1)?1:0,'timeout_seconds'=>max(1,min(120,(int)input('post.timeout_seconds',30))),'description'=>trim((string)input('post.description','')),'updated_at'=>date('Y-m-d H:i:s')];if($upSecret!=='')$data['upstream_auth_secret']=SecretStore::encrypt($upSecret);elseif(!$id)$data['upstream_auth_secret']=null;if($id){$oldSlug=(string)(Db::name('endpoints')->where('id',$id)->value('slug')??'');Db::name('endpoints')->where('id',$id)->update($data);if($oldSlug!=='')GatewayCache::forgetEndpoint($oldSlug);$this->writeAudit('endpoint.update','endpoint',$id,$slug);}else{$data['created_at']=date('Y-m-d H:i:s');$id=Db::name('endpoints')->insertGetId($data);$this->writeAudit('endpoint.create','endpoint',$id,$slug);}GatewayCache::forgetEndpoint($slug);return redirect('/admin/endpoints');}
 public function toggleEndpoint($id){if($r=$this->guard())return $r;$row=Db::name('endpoints')->where('id',(int)$id)->find();if(!$row)return response('Not Found',404);$s=$row['status']?0:1;Db::name('endpoints')->where('id',(int)$id)->update(['status'=>$s,'updated_at'=>date('Y-m-d H:i:s')]);GatewayCache::forgetEndpoint((string)$row['slug']);$this->writeAudit('endpoint.toggle','endpoint',(int)$id,(string)$s);return redirect('/admin/endpoints');}
 public function settings(){if($r=$this->ownerGuard())return $r;$rows=Db::name('settings')->select()->toArray();$set=[];foreach($rows as $x)$set[$x['key']]=$x['value'];View::assign('settings',$set);View::assign('username',Session::get('lumen_admin_username'));View::assign('redisAvailable',extension_loaded('redis'));return View::fetch(root_path().'view/admin/settings.html');}
 public function saveSettings(){if($r=$this->ownerGuard())return $r;$keys=['redis.enabled','redis.host','redis.port','redis.password','redis.database','ratelimit.enabled','ratelimit.key_rpm','ratelimit.user_rpm','ratelimit.ip_rpm','concurrency.enabled','concurrency.key_max','concurrency.user_max','recharge.quota_per_yuan','recharge.bonus_enabled','recharge.bonus_percent','alipay.enabled','alipay.app_id','alipay.seller_id','alipay.public_key','alipay.private_key','alipay.gateway','alipay.notify_url','alipay.return_url','alipay.sign_type','user.initial_quota','user.registration_enabled'];foreach($keys as $k){$field=str_replace('.','_',$k);$v=(string)input('post.'.$field,'');if($k==='user.registration_enabled')$v=$v==='1'?'1':'0';if($k==='alipay.private_key'&&$v!=='')$v=SecretStore::encrypt($v);$old=Db::name('settings')->where('key',$k)->find();if(in_array($k,['redis.password','alipay.private_key'],true)&&$v===''&&$old)continue;$data=['value'=>$v,'type'=>'string','updated_at'=>date('Y-m-d H:i:s')];if($old)Db::name('settings')->where('key',$k)->update($data);else{ $data['key']=$k;$data['created_at']=date('Y-m-d H:i:s');Db::name('settings')->insert($data);}}$r=RedisService::connect();if($r)try{$r->del('lumen:cfg:ratelimit','lumen:cfg:concurrency');}catch(\Throwable $e){}$this->writeAudit('settings.update','settings',null,'redis');return redirect('/admin/settings?saved=1');}
 public function testRedis(){if($r=$this->guard())return $r;if(!extension_loaded('redis'))return json(['ok'=>false,'message'=>'PHP Redis 扩展未安装，Redis 核心服务不可用。'],422);try{$x=new \Redis();$x->connect((string)input('post.host','127.0.0.1'),(int)input('post.port',6379),2);$pw=(string)input('post.password','');if($pw!=='')$x->auth($pw);$x->select((int)input('post.database',0));$pong=$x->ping();return json(['ok'=>true,'message'=>'Redis 连接成功','pong'=>$pong]);}catch(\Throwable $e){return json(['ok'=>false,'message'=>'Redis 连接失败，请检查配置。'],422);}}
 public function payments(){if($r=$this->guard())return$r;$status=trim((string)input('get.status',''));$q=trim((string)input('get.q',''));$b=Db::name('recharge_orders')->alias('o')->leftJoin('users u','u.id=o.user_id')->field('o.*,u.username');if($status!=='')$b->where('o.status',$status);if($q!=='')$b->whereLike('o.order_no|o.provider_trade_no|u.username','%'.$q.'%');$items=$b->order('o.id','desc')->limit(200)->select()->toArray();foreach($items as &$o){$lot=Db::name('quota_lots')->where('source_type','recharge')->where('source_id',$o['id'])->find();$o['paid_remaining']=(int)($lot['paid_remaining']??0);$o['bonus_remaining']=(int)($lot['bonus_remaining']??0);$o['refundable_cents']=$lot&&$lot['paid_quota']?intdiv((int)$lot['paid_amount_cents']*(int)$lot['paid_remaining'],(int)$lot['paid_quota']):0;}unset($o);$events=Db::name('payment_events')->order('id','desc')->limit(100)->select()->toArray();$refunds=Db::name('refund_orders')->alias('r')->leftJoin('recharge_orders o','o.id=r.recharge_order_id')->field('r.*,o.order_no')->order('r.id','desc')->limit(100)->select()->toArray();View::assign(['username'=>Session::get('lumen_admin_username'),'items'=>$items,'events'=>$events,'refunds'=>$refunds,'status'=>$status,'q'=>$q]);return View::fetch(root_path().'view/admin/payments.html');}

 public function audit(){if($r=$this->guard())return $r;$q=trim((string)input('get.q',''));$page=max(1,(int)input('get.page',1));$size=40;$b=Db::name('audit_logs')->alias('a')->leftJoin('admins u','u.id=a.admin_id')->field('a.*,u.username');if($q!=='')$b->whereLike('a.action|a.target_type|a.detail|a.ip|u.username','%'.$q.'%');$count=(clone $b)->count();$items=$b->order('a.id','desc')->page($page,$size)->select()->toArray();View::assign(['items'=>$items,'username'=>Session::get('lumen_admin_username'),'q'=>$q,'page'=>$page,'pages'=>max(1,(int)ceil($count/$size)),'count'=>$count]);return View::fetch(root_path().'view/admin/audit.html');}
 public function editEndpoint($id){if($r=$this->guard())return $r;$item=Db::name('endpoints')->where('id',(int)$id)->find();if(!$item)return response('Not Found',404);View::assign('item',$item);View::assign('params',Db::name('endpoint_params')->where('endpoint_id',(int)$id)->order('sort_order,id')->select()->toArray());View::assign('username',Session::get('lumen_admin_username'));return View::fetch(root_path().'view/admin/endpoint_edit.html');}

 public function testEndpoint($id){
  if($r=$this->guard())return$r;
  $ep=Db::name('endpoints')->where('id',(int)$id)->find();
  if(!$ep)return json(['ok'=>false,'message'=>'LumenAPI：端点不存在'],404);
  $method=strtoupper((string)input('post.method','GET'));
  if(!in_array($method,['GET','POST','PUT','PATCH','DELETE'],true))return json(['ok'=>false,'message'=>'LumenAPI：请求方法无效'],422);
  $query=trim((string)input('post.query',''));$body=(string)input('post.body','');
  $start=microtime(true);
  try{
   if(($ep['driver']??'')==='handler'){
    parse_str(ltrim($query,'?&'),$q);
    $raw=(string)($q['url']??'');
    if($raw===''&&$body!==''){$j=json_decode($body,true);if(is_array($j))$raw=(string)($j['url']??'');}
    if($raw==='')return json(['ok'=>false,'message'=>'LumenAPI：测试 Handler 时请在 Query 填写 url=...，或在 JSON Body 传入 url'],422);
    $handler=\app\api\handlers\HandlerRegistry::make((string)($ep['handler_name']??''));
    $params=$q;
    if($body!==''){$j=json_decode($body,true);if(is_array($j))$params=array_merge($params,$j);}
    $runtimeEp=$ep;$secret=(string)($ep['upstream_auth_secret']??'');$runtimeEp['upstream_auth_secret']=$secret!==''?SecretStore::decrypt($secret):'';
    $hr=$handler->handle($runtimeEp,$method,$params);$elapsed=(int)((microtime(true)-$start)*1000);
    $this->writeAudit('endpoint.test','endpoint',(int)$id,'handler; status='.(int)($hr['status']??500).'; duration_ms='.$elapsed);
    return json(['ok'=>(int)($hr['status']??500)<400,'status'=>(int)($hr['status']??500),'duration_ms'=>$elapsed,'body'=>$hr['body']??[]]);
   }
   $url=(string)$ep['target_url'];if($query!=='')$url.=(str_contains($url,'?')?'&':'?').ltrim($query,'?&');
   $headers=['Accept: application/json','Content-Type: application/json'];$secret=(string)($ep['upstream_auth_secret']??'');$secret=$secret!==''?SecretStore::decrypt($secret):'';
   $type=(string)($ep['upstream_auth_type']??'none');$name=(string)($ep['upstream_auth_name']??'');
   if($type==='bearer'&&$secret!=='')$headers[]='Authorization: Bearer '.$secret;
   elseif($type==='header'&&$secret!==''&&$name!=='')$headers[]=$name.': '.$secret;
   elseif($type==='basic'&&$secret!==''&&$name!=='')$headers[]='Authorization: Basic '.base64_encode($name.':'.$secret);
   elseif($type==='query'&&$secret!==''&&$name!=='')$url.=(str_contains($url,'?')?'&':'?').rawurlencode($name).'='.rawurlencode($secret);
   foreach(preg_split('/\r\n|\r|\n/',(string)($ep['upstream_headers']??'')) as $h)if(trim($h)!=='')$headers[]=trim($h);
   $resp=\app\service\UpstreamHttpService::send($url,$method,$headers,$body,(int)$ep['timeout_seconds'],1048576);$elapsed=(int)((microtime(true)-$start)*1000);
   $decoded=json_decode($resp['body'],true);$preview=json_last_error()===JSON_ERROR_NONE?$decoded:$resp['body'];
   $this->writeAudit('endpoint.test','endpoint',(int)$id,'status='.$resp['status'].'; duration_ms='.$elapsed);
   return json(['ok'=>true,'status'=>$resp['status'],'duration_ms'=>$elapsed,'content_type'=>$resp['content_type'],'body'=>$preview]);
  }catch(\Throwable $e){$this->writeAudit('endpoint.test_failed','endpoint',(int)$id,get_class($e));return json(['ok'=>false,'message'=>'LumenAPI：端点测试执行失败'],422);}
 }
 public function saveEndpointParams($id){if($r=$this->guard())return $r;$id=(int)$id;if(!Db::name('endpoints')->where('id',$id)->find())return response('Not Found',404);$names=(array)input('post.param_name/a',[]);$locs=(array)input('post.param_location/a',[]);$types=(array)input('post.param_type/a',[]);$required=(array)input('post.param_required/a',[]);$defaults=(array)input('post.param_default/a',[]);$descs=(array)input('post.param_description/a',[]);$rows=[];$seen=[];$now=date('Y-m-d H:i:s');foreach($names as $i=>$name){$name=trim((string)$name);if($name==='')continue;if(!preg_match('/^[A-Za-z0-9_.-]{1,100}$/',$name))return response('参数名不合法：'.$name,422);$loc=strtolower((string)($locs[$i]??'query'));$type=strtolower((string)($types[$i]??'string'));if(!in_array($loc,['query','header','body','path'],true)||!in_array($type,['string','integer','number','boolean','json'],true))return response('参数配置不合法',422);$k=$loc.':'.strtolower($name);if(isset($seen[$k]))return response('参数重复：'.$name,422);$seen[$k]=1;$rows[]=['endpoint_id'=>$id,'name'=>$name,'location'=>$loc,'data_type'=>$type,'required'=>isset($required[$i])&&$required[$i]=='1'?1:0,'default_value'=>(string)($defaults[$i]??'')!==''?(string)$defaults[$i]:null,'description'=>mb_substr(trim((string)($descs[$i]??'')),0,500),'sort_order'=>count($rows),'created_at'=>$now,'updated_at'=>$now];}Db::transaction(function()use($id,$rows){Db::name('endpoint_params')->where('endpoint_id',$id)->delete();if($rows)Db::name('endpoint_params')->insertAll($rows);});GatewayCache::forgetEndpointParams($id);$this->writeAudit('endpoint.params.update','endpoint',$id,'count='.count($rows));return redirect('/admin/endpoints/'.$id.'/edit?saved=params');}

}

